import{S as a,o as s,c as n,a9 as i,B as l}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/opencode/07-plan-execute-verify-roles.svg",d="/agentsrc/images/opencode/07-execution-state-machine.svg",r="/agentsrc/images/opencode/07-verification-gates.svg",g=JSON.parse('{"title":"OpenCode 编排模式：plan-execute-verify 的角色拆分、硬边界与验证关卡","description":"","frontmatter":{"title":"OpenCode 编排模式：plan-execute-verify 的角色拆分、硬边界与验证关卡"},"headers":[],"relativePath":"opencode/07-plan-execute-verify.md","filePath":"opencode/07-plan-execute-verify.md","lastUpdated":1788319991000}'),u={name:"opencode/07-plan-execute-verify.md"},k=Object.assign(u,{setup(c){const e=[{question:"范围蔓延的本质是「决策权与执行权未做分离」。plan-execute-verify 编排机制是如何在 Plan（规划）阶段堵住这一风险的？",options:["让规划师直接进行代码实现，以最快速度明确任务边界","给规划师仅配置只读工具，并设置 Hook 硬性拒绝非 .omo 文件的写入","将执行调度权集中在规划师一人手中，以避免范围不定","换用更强的模型让规划师一次性思考到位，从而消除范围蔓延"],correct:1,explanation:"Plan 阶段把决策权（规划师）用只读硬边界隔离——allowed-tools 白名单只放行 .omo/*.md，prometheus-md-only 钩子在 tool.execute.before 上拒绝其余写入。这样规划师无法越界实现，范围蔓延在源头被堵。"},{question:"Execute 阶段为什么要用 boulder.json 持久化编排状态，而不是只依赖 LLM 的上下文？",options:["为了把「现在做什么/做了几件」从易失上下文抽到可查询、可恢复的磁盘状态","为了让模型在处理上下文时有一个更大的 token 缓存减少调用费","为了让用户能随时修改计划文件而不断言流水线一致性","为了把执行调度完全静态化使规划阶段不再需要任何决策"],correct:0,explanation:"boulder.json 记录 plan_name/status/session_ids/进度，把执行状态从 LLM 上下文里抽出。在线程崩溃、关机、token 超限等中断场景下，系统能按磁盘状态续跑而不是重讲一遍——这是「可恢复」这一设计点的落点。"},{question:"COMPLETION GATE 要求执行者 Edit 计划文件把 checkbox 从 - [ ] 改为 - [x]，再 Read 一次确认。这项要求的本质作用是什么？",options:["让执行者每次完成任务都留下一个可核对的进度锚点而非口头声明","让执行者通过反复编辑文件来增加上下文中的信息密度","让执行者以编辑计划为手段来扩大自己对范围的定义权","让执行者在完成后立即关闭会话以节省 token 消耗"],correct:0,explanation:"它把「完成」的唯一证据定义为磁盘文件里 checkbox 的变更，强制执行者在宣称完成前先更新计划文件再读回确认。这样进度锚在计划文件（唯一事实源），执行者不能以「我改完代码了」这类叙述替代可核对的进度变化，堵住验证缺口的最浅形态。"},{question:"VERIFICATION_REMINDER 开头断言「THE SUBAGENT IS PROBABLY LYING」。这种对抗性信念和「信任但验证」的差别在哪？",options:["对抗模式把举证责任交给验证者去证明好，而非执行者自证","对抗模式意味着验证者完全不运行任何确定性工具只看叙述","对抗模式只适用于执行者是子代理而规划师绝对可信的场景","对抗模式用更强模型重复执行同一次自证以提高可信度"],correct:0,explanation:"信任但验证把举证责任交给执行者（自证做对）；对抗模式假设坏、要求验证者用 git diff/Read/lsp_diagnostics/跑测试等确定性工具主动证明好，并把证据链抓在手里。幻觉是 base rate，验证者手里的可复现证据链才稳。"},{question:"Final Verification Wave 在整套编排里扮演什么角色，为何它是唯一需要用户审批的时刻？",options:["它是执行前的计划确认要用户先点头再审阅文档","它把收尾统验与唯一用户审批点集中在最后避免频繁打断","它是执行态每轮任务的常规进度汇报途径","它允许验证者在任何关卡直接跳过用户直接放行"],correct:1,explanation:"所有实现 todo 勾完后才进入 Final Wave 统验批次，且它由 shouldPauseForApproval 决定走审批路径，是唯一要求用户显式点头后再标记终审项的时刻。规划、执行、自动验证全程不打扰人，只在结尾把终审结论交用户裁决——既不让机器脱离人判断，也不让人反复被打断。"}];return(h,t)=>{const o=a("Quiz");return s(),n("div",null,[t[0]||(t[0]=i("",96)),l(o,{questions:e})])}}});export{g as __pageData,k as default};
